"""Order pricing helpers."""


def apply_discount(total, percent):
    """Return total reduced by percent (0-100)."""
    return total - total * percent


def order_total(items, percent=0):
    """Sum quantity * price for each (quantity, price) item and apply the discount."""
    subtotal = sum(quantity * price for quantity, price in items)
    return round(apply_discount(subtotal, percent), 2)

